#!/usr/bin/env python3
"""Root decisions following direct inspection of all 24 differing blind crops."""
from pathlib import Path
import csv,json
R=Path(__file__).resolve().parents[1];stem='H156-01_156-7_scan004'
bs={x['box']:[int(x[k]) for k in ('x0','y0','x1','y1')] for x in csv.DictReader((R/'second'/f'{stem}_boxes.tsv').open(),delimiter='\t')}
cfg={'reader':'reader_a (GPT-6 Astra Pro; effort not exposed)','patches':[],'change_updates':{},'new_changes':[],'remove_doubt_places':['bottom-left marginal word'],'new_doubts':[],'boxes':{}}
def patch(a,b):cfg['patches'].append({'old':a,'new':b,'count':1})
connector=r'\tikz[x=1em,y=1em]{\draw (0,0) .. controls (-.3,.7) and (-.15,1.1) .. (.4,1.2)--(4.7,1.35)--(4.75,1.6);}'
patch('je suis resté muet',r'\unsure{je|y} suis resté muet')
patch("l'ens. des lieux",r"l'\unsure{ens.|un.} des lieux")
patch("cela signifie qu'on a un",r"\unsure{cela|cel} signifie qu'on a un")
patch(r'\uline{NB} Existe dans',r'\uline{NB} \unsure{Exist|Existe} dans')
patch(r'\unsure{mechisé|méchisé}',r'\unsure{mechisé|méchisé|métrisé}')
patch(r'\inserted{ou Inf pour $\leq$}',r'\inserted{'+connector+r'\enspace ou Inf pour $\leq$}')
patch(r'figure vide : plus petit élément de',r'figure vide : plus petit \unsure{élément|élémt} de')
E={
'B001':('retain; wrapper only','The single handwritten digit is 3. The second reading adds mspage around the excerpt; that wrapper already exists in the page.',[]),
'B002':('mark uncertainty','The compressed first group has a descending left stem and joined upper/right curve. These can be je with a flattened e or a single y-shaped form; the identifying separation is not secure. Retain je first with y as an alternative. The strokes of suis resté muet are unchanged.',['004-A01']),
'B003':('retain GF and both bars','The first open bowl ends in a distinct downward returned terminal, unlike a plain unreturned C; retain G. F has both bars. VI has an upper and a lower horizontal rule; nesting underline/overline in the reverse order changes no source mark.',[]),
'B005':('mark abbreviated-word uncertainty; retain L and deletion doubts','The abbreviation after l’ has very flattened joined humps and a following point. Ens. remains plausible, but the same compressed outline permits un.; preserve both. The L loop cannot settle ordinary versus calligraphic font at its first occurrence. The crossed following group preserves a loop and fused low strokes; not every letter is plain, so ou/de/ce remain rather than resolving to ou.',['004-A02']),
'B006':('mark uncertainty','The opening group has c/e curves and a tall l loop, followed by a flat exit. A compressed terminal a may be merged into that exit, but cel cannot be excluded. Retain cela first and cel as an alternative; signifie qu’on a un is unchanged.',['004-A03']),
'B007':('retain comma','A separate dark curved short stroke sits just to the lower right of the closing parenthesis. Its position and weight support the comma already transcribed, rather than omitting it.',[]),
'B009':('retain first','Live pre precedes the narrow crossed group and mières follows it. The possible accent is tangled with the correction; no independent absence is established. A tall loop and narrow stroke remain compatible with l/li beneath the strike, so preserve these uncertain readings rather than replacing all the old ink by illegible. Both heading underlines and final colon remain.',[]),
'B010':('retain first-occurrence alphabet doubt','The family F has a looped top swash, crossed stem and curved lower end. The scan cannot choose conclusively between intentional mathscr and mathcal alphabets; retain the first-occurrence alternatives and the same primary mapping on later pages. Added font braces are syntax only.',[]),
'B011':('retain both doubts','The repeated tall/looped strokes after re cannot safely be segmented between one and two l forms. The word before figures has a long final horizontal run, which may be an e exit or contain a compressed s. Retain rellation/relation and de/des. The inclusion underline is unchanged.',[]),
'B012':('retain first','The label contains d/e/f strokes crowded beneath the preceding line; an accent cannot be securely isolated or excluded. Keep déf/def. The whole formula has inclusion on the left, two shafts with heads at both ends, and F sous figure de G on the right. Text/roman wrappers and math delimiter placement do not alter its words or signs.',[]),
'B013':('retain page; excerpt coverage and syntax only','Relation de raffinement is plainly on the preceding baseline and already present in the page. The first box excerpt began at the formula; the second included that preceding line. Def has no independent accent stroke here. The formula F≪G iff F raffine G agrees; text/roman wrappers and delimiters are equivalent.',[]),
'B014':('retain page; excerpt coverage and spacing only','Avec is visible above the formula and already present in the page. At alone is underlined; 0 is outside the rule. The entire implication F≤G ⇒ F≪G agrees. Including avec in this excerpt and adding quad are not page corrections.',[]),
'B015':('retain; tie only','At is underlined and 4 is clear outside the rule. The wording NB. Ce sera aussi contenu dans At 4 plus bas agrees; tie versus ordinary space changes no inscription.',[]),
'B017':('retain; size and spacing only','The enclosed a, join and union signs and both Gs agree. Scriptsize and quad only control typesetting size/space.',[]),
'B019':('retain punctuation doubt','The closing mark after existe has a curled/crossed upper lobe and long lower curve. A right parenthesis and malformed brace both remain possible; the unqualified second parenthesis does not settle it. The whole qualification and following refinement supremum text agree.',[]),
'B021':('retain; braces and spacing only','The note has underlined NB and a tilde extending over F∩G, equal to separate tilde F and tilde G. Adding groups around individual tilde arguments and quad does not change these strokes.',[]),
'B022':('retain small-argument doubt','The small second argument of Inf is an open c-shaped bowl without a secure inward G bar. The larger surrounding Gs do not resolve this reduced form, so c/G remains. Circled-label size, quad and positioning math delimiters are representational only; both wedge and cap forms agree.',[]),
'B023':('reproduce attachment line; retain words and literal C','The inserted ou Inf pour ≤ has a long line beneath it, with a short upturned right end and a left bend descending toward intersection. Reproduce this omitted connector inside the insertion. Inf in text versus roman math and bar versus overline on m are typesetting differences. The stroke before m has a crossed/hooked base, so the parenthesis/et-parenthesis doubt stays. Infinie and vide have no separable final s; their existing singular forms stand. The F∨C operand is an open flat-bottomed C without an internal G hook. The remaining punctuation and words agree.',['004-A06']),
'B024':('revise opening word and widen final-word doubt','After Exis the tall crossed t ends without a separately recoverable final e loop; Exist is the better literal reading, while a compressed Existe remains possible. The final adjective has an m-like onset, a connected medial loop/ascender, dotted i and accented ending. A compressed tr sequence cannot be excluded from that middle cluster, so add métrisé beside mechisé/méchisé rather than deciding by vocabulary.',['004-A04','004-A05']),
'B025':('retain governed c reading and label doubt','The circled inner letter remains entangled with its enclosure, so its c doubt stays. The multiplication-like dot is low on the baseline; period versus mathbin/ldotp is representational here. The Inf argument repeats the small c-shaped form of row b; the c/G uncertainty is already registered at that first occurrence and explicitly governs this repetition. No duplicate doubt is added. All surrounding formula signs agree.',[]),
'B026':('retain; math wrapper only','Inf consists of the same capital I, n and long f whether put into roman math or ordinary text. Both separate underlines and the absence of closing quotation marks remain. The parenthesis, colon and final period agree.',[]),
'B027':('retain doubtful candidates','The crossed group retains one open bowl and further loop/bar residue compatible with G or CG. The crossings prevent a full identification but do not make every underlying stroke unreadable. Preserve the candidates and their deletion state.',[]),
'B028':('retain first','The empty-figure symbol is an oval crossed by a pronounced diagonal slash running down-left/up-right; retain varnothing rather than a vertical-stem phi. Its script-F subscript follows the first-occurrence font doubt. The circled d remains uncertain in both readings. Scriptsize and quad are typesetting only.',[]),
'B029':('mark full-word/abbreviation uncertainty','The neutral crop clipped the last word, so a single root blind crop extends it to the physical sheet edge. The accented initial é, tall l and following é are visible; the rest is a flattened run followed by t. It admits both full élément and abbreviated élémt. The final t is not securely raised, so an unqualified superscript abbreviation is not adopted. Mark the word doubtful. The ambient-F alphabet is already governed by its first-occurrence doubt; both inequalities, parentheses and underlined et agree.',['004-A07'])
}
for b,(decision,evidence,ids) in E.items():cfg['boxes'][b]={'crop':f'crops/second_scan004_{b}.png','box_coords':bs[b],'decision':decision,'evidence':evidence,'changed_place_ids':ids}
cfg['boxes']['B029']['crop']='crops/second_scan004_B029_root_extent.png';cfg['boxes']['B029']['box_coords']=[969,2185,1680,2360]
def upd(id,b,**kw):cfg['change_updates'][id]={'crop':cfg['boxes'][b]['crop'],'box':cfg['boxes'][b]['box_coords'],**kw}
upd('S004-010','B006',final=r'\unsure{cela|cel}',scan_shows=E['B006'][1],confidence='low')
upd('S004-027','B023',final=r'\inserted{'+connector+r'\enspace ou Inf pour $\leq$}',scan_shows='The phrase attaches to intersection in row (b). Its bottom horizontal connector turns upward at the right and bends down at the left toward that word. Both witnesses omit the line drawing; H additionally places the phrase with (a).',against_C=True)
upd('S004-041','B024',final=r'\unsure{mechisé|méchisé|métrisé}',scan_shows=E['B024'][1],confidence='low')
cfg['new_changes'].append({'id':'S004-049','place':'bottom-left marginal note, opening verb','C':'Existe','H':'Existe','final':r'\unsure{Exist|Existe}','scan_shows':'The final t has its tall stem and crossbar, but no separate following e loop is recoverable. Exist is the primary literal reading; a fused e remains possible.','confidence':'low','kind':'misread word','crop':'crops/second_scan004_B024.png','box':bs['B024'],'against_C':True,'against_H':True,'marked_in_H':False,'consequential':False})
for place,reading,alts,b in [
 ('opening phrase before suis resté muet','je',['y'],'B002'),
 ('opening block, abbreviation before des lieux','ens.',['un.'],'B005'),
 ('parenthetical phrase before signifie','cela',['cel'],'B006'),
 ('bottom-left marginal note, opening verb','Exist',['Existe'],'B024'),
 ('bottom-left marginal word','mechisé',['méchisé','métrisé'],'B024'),
 ('empty figure description, word after plus petit','élément',['élémt'],'B029')]:cfg['new_doubts'].append({'place':place,'reading':reading,'alternatives':alts,'confidence':'low','reason':E[b][1]})
(R/'second'/f'{stem}_decisions.json').write_text(json.dumps(cfg,ensure_ascii=False,indent=2)+'\n')
(R/'review'/'root_scan004_blind_observations.md').write_text('# Root blind adjudication, scan004\n\nAll 24 differing boxes were directly viewed. B029 required one documented extension to the physical sheet edge because the neutral box clipped its final word.\n\n'+'\n'.join(f'- **{b}**: {v[1]}' for b,v in E.items())+'\n')
print('Wrote',len(E),'decisions;',len(cfg['patches']),'changed places.')
